return "\nget_adventure_score 10600 {\n    request {\n        mode        0 : integer\n        modetype    1 : integer\n    }\n    response {\n        result      0 : integer\n        score       1 : integer\n        rank        2 : integer\n\n        .modescore {\n            mode    0 : integer\n            score   1 : integer\n        }\n\n        modescore   3 : *modescore\n    }\n}\n\nis_have_adventure_awards 10601 {\n    request {\n        mode        0 : integer\n        modetype    1 : integer\n    }\n    response {\n        result      0 : integer\n        exchangedscore 1 : integer  #已经兑换的积分\n        canexchangescore 2 : integer #可以兑换的积分\n        items       3 : *dropids\n\n        .awardlist {\n            rank    0 : integer\n            havereceived 1 : boolean\n        }\n\n        awardlist   4 : *awardlist\n    }\n}\n\nget_adventure_score_awards 10602 {\n    request {\n        mode        0 : integer\n        modetype    1 : integer\n        rank        2 : integer\n    }\n    response {\n        result      0 : integer\n        gold        1 : integer\n        diamond     2 : integer\n        sp          3 : integer\n        items       4 : *item\n    }\n}\n\nget_adventure_score_ranklist 10603 {\n    request {\n        mode        0 : integer\n        modetype    1 : integer\n        start       2 : integer\n        stop        3 : integer\n    }\n    response {\n        result 0 : integer\n\n        .rankdata {\n            playerid        0 : integer\n            name            1 : string\n            score           2 : integer\n            head_sculpture  3 : string\n            level           4 : integer\n            medal_1         5 : integer\n            medal_2         6 : integer\n            medal_3         7 : integer\n            rank            8 : integer\n            star            9 : integer\n        }\n\n        data 1 : *rankdata\n    }\n}\n\n#无限竞速\n\nswitch_to_infinitemode 10604 {\n    request {\n        mode 0 : integer\n        battlearray 1 : battle_array    #废弃\n    }\n    response {\n        result      0 : integer\n        levelmode   1 : modeconfig\n        curlevel    2 : string\n        curmode     3 : integer\n        fightdata   4 : *arena_totalfightdata\n    }\n}\n\npass_infinite 10605 {\n    request {\n        mode    0 : integer\n        damage  1 : string\n    }\n    response {\n        result      0 : integer\n        score       1 : integer\n        levelmode   2 : modeconfig\n        curlevel    3 : string\n        curmode     4 : integer\n        totaltime   5 : integer\n    }\n}\n\nsync_infinite_time 10606 {\n    request {\n        dt  0 : string\n        damage 1 : string\n    }\n    response {\n        result  0 : integer\n        score   1 : integer\n        time    2 : string\n    }\n}\n\nget_infinite_score_up_list 10607 {\n    request {\n        mode 0 : integer\n    }\n    response {\n        .scoreuplist {\n            servantid 0 : integer\n            up 1 : string\n        }\n\n        list 0 : *scoreuplist\n    }\n}\n\ntower_defence_cost_item 10608 {\n    request {\n        mode 0 : integer\n        chapter 1 : integer\n        costtype 2 : integer\n        isrefresh 3 : integer\n        add_free_cost 4 : integer\n    }\n\n    response {\n        result 0 : integer\n        costitemid 1 : integer\n        costnum 2 : integer\n        costdiamond 3 : integer\n        free_xp_count 4 : integer\n    }\n}\n\nget_tower_defence_info 10609 {\n    response {\n        result 0 : integer\n        season 1 : integer      #赛季id,0表示无\n        starttime 2 : integer\n        finishtime 3 : integer\n        modelist 4 : *integer\n        modeconfiglist 5 : *modeconfig\n    }\n}\n\n# 获取周爬塔信息\nget_weektower_info 10610 {\n    response {\n        .item {\n            cityid 0 : integer          #城市id\n            skills 1 : string           #已获得的技能列表(chapter:skillid|chapter:skillid)\n        }\n        result 0 : integer\n        citylist 1 : *item              #城市列表\n        modelist 2 : *modeconfig        #被重置的mode列表\n    }\n}\n\n# 设置周爬塔技能\nset_weektower_skill 10611 {\n    request {\n        cityid      0 : integer\n        chapterid   1 : integer\n        skillid     2 : integer\n    }\n    response {\n        result      0 : integer         #0配置错误,1成功,2已经激活该档技能\n    }\n}\n\n"
